    if not os.path.isfile(filepath):
        return {
            "check_name": f"not_empty_{os.path.basename(filepath)}",
            "passed": False,
            "message": f"File {filepath} is missing"
        }

    size = os.path.getsize(filepath)
    is_not_empty = size > 0
    return {
        "check_name": f"not_empty_{os.path.basename(filepath)}",
        "passed": is_not_empty,
        "message": f"File {filepath} has {size} bytes" if is_not_empty else f"File {filepath} is empty"
    }


def check_csv_has_columns(filepath: str, expected_columns: list) -> dict:
    """Check if a CSV file has the expected columns."""
    if not os.path.isfile(filepath):
        return {
            "check_name": f"columns_{os.path.basename(filepath)}",
            "passed": False,
            "message": f"File {filepath} is missing"
        }

    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            reader = csv.reader(f)
            header = next(reader, None)

            if header is None:
                return {
                    "check_name": f"columns_{os.path.basename(filepath)}",
                    "passed": False,
                    "message": f"File {filepath} has no header row"
                }

            missing = [col for col in expected_columns if col not in header]
            has_columns = len(missing) == 0

            return {
                "check_name": f"columns_{os.path.basename(filepath)}",
                "passed": has_columns,
                "message": f"File {filepath} has all expected columns" if has_columns else f"File {filepath} is missing columns: {missing}"
            }
    except Exception as e:
        return {
            "check_name": f"columns_{os.path.basename(filepath)}",
            "passed": False,
            "message": f"Error reading {filepath}: {str(e)}"
        }


