    """Check if a CSV file has at least the minimum number of data rows."""
    if not os.path.isfile(filepath):
        return {
            "check_name": f"rows_{os.path.basename(filepath)}",
            "passed": False,
            "message": f"File {filepath} is missing"
        }

    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            reader = csv.reader(f)
            next(reader, None)  # Skip header
            row_count = sum(1 for _ in reader)

            has_enough_rows = row_count >= min_rows

