        return {
            "check_name": f"rows_{os.path.basename(filepath)}",
            "passed": False,
            "message": f"Error reading {filepath}: {str(e)}"
        }


def main():
    """Run all validation checks and write summary to JSON."""
    results = []

    # Define files and their expected columns
    files_to_check = [
        {
            "path": "outputs/t01_selected_indicators.csv",
            "columns": ["indicator_id", "indicator_name", "theme", "justification", "expected_direction"],
            "min_rows": 5
        },
        {
            "path": "outputs/t05_clean_stops.csv",
            "columns": ["stop_id", "stop_name", "stop_lat", "stop_lon"],
            "min_rows": 10
