            "columns": ["qid", "label", "poi_type", "latitude", "longitude", "source"],
            "min_rows": 5
        },
        {
            "path": "outputs/t10_accessibility_scores.csv",
            "columns": ["qid", "label", "poi_type", "distance_m", "n_departures", "n_routes", "accessibility_score"],
            "min_rows": 5
        },
        {
            "path": "outputs/t13_city_clusters.csv",
            "columns": ["city_id", "city_name", "year", "cluster_id"],
            "min_rows": 10
        }
    ]

    for file_info in files_to_check:
        filepath = file_info["path"]

        # Check file exists
        results.append(check_file_exists(filepath))

        # Check file not empty
        results.append(check_file_not_empty(filepath))

        # Check columns
        results.append(check_csv_has_columns(filepath, file_info["columns"]))

        # Check row count
        results.append(check_csv_has_rows(filepath, file_info["min_rows"]))

    # Write results to JSON
    output_path = "outputs/t14_validation_summary.json"
    os.makedirs(os.path.dirname(output_path), exist_ok=True)

    with open(output_path, 'w', encoding='utf-8') as f:
        json.dump(results, f, indent=2)

    # Print summary
    passed_count = sum(1 for r in results if r["passed"])
    total_count = len(results)
    print(f"Validation complete: {passed_count}/{total_count} checks passed")
    print(f"Results written to {output_path}")


if __name__ == "__main__":
    main()
